  function fillServiceSelectors(data){const rep=$('installationServiceRepresentative'),current=rep?.value||'';if(rep){rep.innerHTML='<option value="">كل المندوبين</option>'+(data.representatives||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');rep.value=current}const incoming=data.teams||[],allowed=new Set(incoming.map(x=>String(x.id)));state.serviceTeams=incoming;if(!state.serviceTeamsInitialized){state.serviceSelectedTeams=new Set(incoming.map(x=>String(x.id)));state.serviceTeamsInitialized=true}else{state.serviceSelectedTeams=new Set([...state.serviceSelectedTeams].filter(x=>allowed.has(x)))}renderServiceTeamOptions()}
  function buildServiceAnalytics(data){const map=new Map();for(const team of data.rows||[]){for(const svc of team.services||[]){const key=String(svc.name||'خدمة غير محددة');let row=map.get(key);if(!row){row={name:key,executions:0,quantity:0,value:0,expenses:0,profit:0};map.set(key,row)}row.executions+=Number(svc.executions||0);row.quantity+=Number(svc.quantity||0);row.value+=Number(svc.value||0);row.expenses+=Number(svc.expenses||0);row.profit+=Number(svc.profit||0)}}const rows=[...map.values()].map(x=>{const margin=x.value?Math.round((x.profit/x.value)*1000)/10:0,costRate=x.value?Math.round((x.expenses/x.value)*1000)/10:0,average=x.quantity?x.value/x.quantity:0,averageCost=x.quantity?x.expenses/x.quantity:0,averageProfit=x.quantity?x.profit/x.quantity:0;return {...x,margin,costRate,average,averageCost,averageProfit}}).sort((a,b)=>b.value-a.value||b.profit-a.profit||a.name.localeCompare(b.name,'ar'));const totals=rows.reduce((a,x)=>({executions:a.executions+x.executions,quantity:a.quantity+x.quantity,value:a.value+x.value,expenses:a.expenses+x.expenses,profit:a.profit+x.profit}),{executions:0,quantity:0,value:0,expenses:0,profit:0});totals.margin=totals.value?Math.round((totals.profit/totals.value)*1000)/10:0;totals.costRate=totals.value?Math.round((totals.expenses/totals.value)*1000)/10:0;totals.average=totals.quantity?totals.value/totals.quantity:0;totals.averageCost=totals.quantity?totals.expenses/totals.quantity:0;totals.averageProfit=totals.quantity?totals.profit/totals.quantity:0;const byProfit=rows.slice().sort((a,b)=>b.profit-a.profit),byRevenue=rows.slice().sort((a,b)=>b.value-a.value),byExecutions=rows.slice().sort((a,b)=>b.executions-a.executions||b.quantity-a.quantity),byMargin=rows.slice().sort((a,b)=>b.margin-a.margin||b.profit-a.profit),byExpenses=rows.slice().sort((a,b)=>b.expenses-a.expenses),byLowMargin=rows.slice().sort((a,b)=>a.margin-b.margin||a.profit-b.profit);return {rows,totals,byProfit,byRevenue,byExecutions,byMargin,byExpenses,byLowMargin}}
  function serviceRanking(rows,metric,formatter){if(!rows.length)return '<div class="installation-service-ranking-empty">لا توجد بيانات.</div>';const max=Math.max(1,...rows.slice(0,5).map(x=>Math.max(0,Number(x[metric]||0))));return rows.slice(0,5).map((x,i)=>`<div class="installation-service-ranking-row"><span class="installation-service-ranking-index">${i+1}</span><div><strong>${esc(x.name)}</strong><div class="installation-service-ranking-track"><i style="width:${Math.max(4,Math.round(Math.max(0,Number(x[metric]||0))/max*100))}%"></i></div></div><b>${formatter(x[metric])}</b></div>`).join('')}
  function validMinutes(a,b){if(!a||!b)return null;const x=new Date(a).getTime(),y=new Date(b).getTime(),m=(y-x)/60000;return Number.isFinite(m)&&m>=0?m:null}
