    const rep=$('installationServiceRepresentative')?.selectedOptions?.[0]?.textContent||'كل المندوبين',teams=state.serviceSelectedTeams.size===state.serviceTeams.length?'كل الفرق':state.serviceSelectedTeams.size?`${state.serviceSelectedTeams.size} فرق`:'لا توجد فرق';$('installationServiceOperationalFilterLabel').textContent=serviceFilterLabel();
